input.command:
cd /home/user/fortress; wait_for () {    local n=0 max=${2:-270}
        while ! grep -q '^EXIT=' "$1" 2>/dev/null ; do
            sleep 5 ; n=$((n+5))
            [ "$n" -ge "$max" ] && { echo "still running after ${n}s" ; return 1 ; }
        done
        grep -n '^BUILD \|^Total time:\|^OK (\|^FAILURES!!!\|^Tests run:\|^EXIT=' "$1"
    }; wait_for tmp/gate-batch-25/compileAll.txt; grep -n 'Caches' tmp/gate-batch-25/compileAll.txt

